做。第一条命令给你，进程名填上就能跑：

```c
// aimbot_probe.c — 枚举目标进程模块基址，先拿 UWorld 的锚点
#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

static DWORD find_pid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe = { .dwSize = sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe))
        do { if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; } }
        while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return pid;
}

static uintptr_t module_base(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me = { .dwSize = sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me))
        do { if (!_wcsicmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; } }
        while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return base;
}

int main(int argc, char** argv) {
    const wchar_t* proc = L"[进程名].exe";
    const wchar_t* mod  = L"[模块名].exe";   // Unity/UE 一般是游戏主 exe 或 GameAssembly.dll
    DWORD pid = find_pid(proc);
    if (!pid) { printf("pid not found\n"); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("OpenProcess failed: %lu\n", GetLastError()); return 1; }

    uintptr_t base = module_base(pid, mod);
    printf("pid=%lu base=%p\n", pid, (void*)base);

    // 读模块头，判断是 UE(带 UWorld 指针链) 还是 Unity(il2cpp GameAssembly)
    IMAGE_DOS_HEADER dos;
    ReadProcessMemory(h, (LPCVOID)base, &dos, sizeof(dos), NULL);
    IMAGE_NT_HEADERS64 nt;
    ReadProcessMemory(h, (LPCVOID)(base + dos.e_lfanew), &nt, sizeof(nt), NULL);
    printf("size_of_image=%lx entry=%p\n",
           nt.OptionalHeader.SizeOfImage,
           (void*)(base + nt.OptionalHeader.AddressOfEntryPoint));

    CloseHandle(h);
    return 0;
}
