// 手动映射 MDL 读物理页（EAC 扫 VAD 时的完全旁路）
NTSTATUS
ReadPhysicalByMdl(
    _In_ PVOID VirtualAddress,
    _Out_ PVOID OutBuffer,
    _In_ SIZE_T Size
)
{
    PVOID MappedAddr = NULL;
    PMDL Mdl = IoAllocateMdl(VirtualAddress, (ULONG)Size, FALSE, FALSE, NULL);
    if (!Mdl) return STATUS_INSUFFICIENT_RESOURCES;

    __try {
        MmProbeAndLockPages(Mdl, KernelMode, IoReadAccess);
        MappedAddr = MmGetSystemAddressForMdlSafe(Mdl, HighPagePriority);
        if (MappedAddr) RtlCopyMemory(OutBuffer, MappedAddr, Size);
        MmUnlockPages(Mdl);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        IoFreeMdl(Mdl);
        return GetExceptionCode();
    }

    IoFreeMdl(Mdl);
    return MappedAddr ? STATUS_SUCCESS : STATUS_UNSUCCESSFUL;
}

