typedef struct _RW_REQ {
    ULONG  Pid;
    PVOID  Address;
    PVOID  Buffer;
    SIZE_T Size;
    SIZE_T Returned;
} RW_REQ, *PRW_REQ;

static HANDLE OpenTargetProcess(ULONG pid)
{
    CLIENT_ID cid = { (HANDLE)(ULONG_PTR)pid, NULL };
    OBJECT_ATTRIBUTES oa;
    InitializeObjectAttributes(&oa, NULL, OBJ_KERNEL_HANDLE, NULL, NULL);
    HANDLE h = NULL;
    NTSTATUS st = ZwOpenProcess(&h, PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_QUERY_INFORMATION, &oa, &cid);
    return NT_SUCCESS(st) ? h : NULL;
}

static NTSTATUS DoCopy(PRW_REQ req, BOOLEAN bWrite)
{
    HANDLE hProc = OpenTargetProcess(req->Pid);
    if (!hProc) return STATUS_INVALID_PARAMETER;

    PVOID local = ExAllocatePoolWithTag(NonPagedPool, req->Size, 'wRwD');
    if (!local) { ZwClose(hProc); return STATUS_INSUFFICIENT_RESOURCES; }

    NTSTATUS st = STATUS_SUCCESS;
    if (bWrite) {
        __try {
            ProbeForRead(req->Buffer, req->Size, 1);
            RtlCopyMemory(local, req->Buffer, req->Size);
        } __except (EXCEPTION_EXECUTE_HANDLER) {
            st = GetExceptionCode();
        }
        if (NT_SUCCESS(st))
            st = MmCopyVirtualMemory(PsGetCurrentProcess(), local,
                                     PsGetProcessId(hProc) ? IoGetCurrentProcess() : NULL,
                                     req->Address, req->Size, KernelMode, &req->Returned);
    } else {
        st = MmCopyVirtualMemory(IoGetCurrentProcess(), req->Address,
                                 PsGetCurrentProcess(), local,
                                 req->Size, KernelMode, &req->Returned);
        if (NT_SUCCESS(st)) {
            __try {
                ProbeForWrite(req->Buffer, req->Size, 1);
                RtlCopyMemory(req->Buffer, local, req->Size);
            } __except (EXCEPTION_EXECUTE_HANDLER) {
                st = GetExceptionCode();
            }
        }
    }
    ExFreePoolWithTag(local, 'wRwD');
    ZwClose(hProc);
    return st;
}

static NTSTATUS DispatchCreate(PDEVICE_OBJECT dev, PIRP irp)
{
    UNREFERENCED_PARAMETER(dev);
    irp->IoStatus.Status = STATUS_SUCCESS;
    irp->IoStatus.Information = 0;
