static NTSTATUS DispatchIoctl(PDEVICE_OBJECT dev, PIRP irp)
{
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION sl = IoGetCurrentIrpStackLocation(irp);
    PVOID buf = irp->AssociatedIrp.SystemBuffer;
    ULONG inLen = sl->Parameters.DeviceIoControl.InputBufferLength;
    ULONG code = sl->Parameters.DeviceIoControl.IoControlCode;
    NTSTATUS st = STATUS_INVALID_PARAMETER;

    if (inLen >= sizeof(RW_REQ)) {
        PRW_REQ req = (PRW_REQ)buf;
        req->Returned = 0;
        switch (code) {
        case IOCTL_READ:  st = DoCopy(req, FALSE); break;
        case IOCTL_WRITE: st = DoCopy(req, TRUE);  break;
        default: break;
        }
    }
    irp->IoStatus.Status = st;
    irp->IoStatus.Information = NT_SUCCESS(st) ? sizeof(RW_REQ) : 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

