int main(void) {
    HMODULE nt = GetModuleHandleW(L"ntdll.dll");
    PFN_NtOpenDirectoryObject    pOpen  = (PFN_NtOpenDirectoryObject)GetProcAddress(nt, "NtOpenDirectoryObject");
    PFN_NtQueryDirectoryObject   pQuery = (PFN_NtQueryDirectoryObject)GetProcAddress(nt, "NtQueryDirectoryObject");

    UNICODE_STRING name;
    RtlInitUnicodeString(&name, L"\\Device");
    OBJECT_ATTRIBUTES oa;
    InitializeObjectAttributes(&oa, &name, OBJ_CASE_INSENSITIVE, NULL, NULL);

    HANDLE hDir = NULL;
    if (!NT_SUCCESS(pOpen(&hDir, GENERIC_READ, &oa))) { printf("open \\Device failed\n"); return 1; }

    BYTE buf[0x4000]; ULONG ctx = 0, ret = 0;
    while (NT_SUCCESS(pQuery(hDir, buf, sizeof(buf), TRUE, FALSE, &ctx, &ret))) {
        for (POBJECT_DIRECTORY_INFORMATION e = (POBJECT_DIRECTORY_INFORMATION)buf;
             e->Name.Length; e = (POBJECT_DIRECTORY_INFORMATION)((BYTE*)e + sizeof(*e) + e->Name.Length)) {
            WCHAR n[256] = {0};
            wcsncpy(n, e->Name.Buffer, min(e->Name.Length / 2, 255));
            if (_wcsicmp(n, L"ACE-BASE") == 0 || wcsstr(n, L"ACE") || wcsstr(n, L"anticheat"))
                wprintf(L"[+] device: %s  type=%lu\n", n, e->Type);
        }
        if (ret == 0) break;
    }
    return 0;
}
