// 从 PsLoadedModuleList 摘除自身
VOID UnlinkFromModuleList(PDRIVER_OBJECT DriverObject) {
    PKLDR_DATA_TABLE_ENTRY entry =
        (PKLDR_DATA_TABLE_ENTRY)DriverObject->DriverSection;   // DriverSection 即 LDR 项
    if (!entry) return;

    // dump 原值，便于回滚
