    DbgPrint("[hide] BaseDllName=%wZ DllBase=%p\n",
             &entry->BaseDllName, entry->DllBase);

    PLIST_ENTRY prev = entry->InLoadOrderLinks.Blink;
    PLIST_ENTRY next = entry->InLoadOrderLinks.Flink;
    prev->Flink = next;
    next->Blink = prev;
    // 保留 InLoadOrderLinks 指向自己，卸载时能原样恢复（见 UnhideModule）
    entry->InLoadOrderLinks.Flink = &entry->InLoadOrderLinks;
