    UINT32 full_len = sizeof(L"\\Driver\\") + DrvName->Length + sizeof(WCHAR);
    PWSTR full = (PWSTR)ExAllocatePoolWithTag(NonPagedPool, full_len, 'hidM');
    if (!full) return STATUS_INSUFFICIENT_RESOURCES;

    RtlCopyMemory(full, L"\\Driver\\", sizeof(L"\\Driver\\") - sizeof(WCHAR));
    RtlCopyMemory((PUCHAR)full + (sizeof(L"\\Driver\\") - sizeof(WCHAR)),
                  DrvName->Buffer, DrvName->Length);
    *(PWSTR)((PUCHAR)full + full_len - sizeof(WCHAR)) = 0;

    UNICODE_STRING path;
    RtlInitUnicodeString(&path, full);
    InitializeObjectAttributes(&oa, &path, OBJ_CASE_INSENSITIVE, NULL, NULL);

    NTSTATUS st = NtOpenDirectoryObject(&h, DIRECTORY_TRAVERSE, &oa);
