static void UnlinkFromPeb(HMODULE hMod) {
    PPEB peb = (PPEB)__readgsqword(0x60);
    PPEB_LDR_DATA ldr = peb->Ldr;
    PLIST_ENTRY head = &ldr->InLoadOrderModuleList;
    for (PLIST_ENTRY e = head->Flink; e != head; e = e->Flink) {
        // CONTAINING_RECORD 到 LDR_DATA_TABLE_ENTRY
        PLDR_DATA_TABLE_ENTRY m = CONTAINING_RECORD(e, LDR_DATA_TABLE_ENTRY, InLoadOrderLinks);
        if (m->DllBase == (PVOID)hMod) {
            RemoveEntryList(&m->InLoadOrderLinks);
            RemoveEntryList(&m->InMemoryOrderLinks);
            RemoveEntryList(&m->InInitializationOrderLinks);
            m->InLoadOrderLinks.Flink = m->InLoadOrderLinks.Blink = &m->InLoadOrderLinks;
            m->InMemoryOrderLinks.Flink = m->InMemoryOrderLinks.Blink = &m->InMemoryOrderLinks;
            m->InInitializationOrderLinks.Flink = m->InInitializationOrderLinks.Blink = &m->InInitializationOrderLinks;
            return;
        }
    }
