static VOID UnlinkLoadedModule(PVOID base) {
    PLIST_ENTRY head = &PsLoadedModuleList;
    for (PLIST_ENTRY e = head->Flink; e != head; e = e->Flink) {
        PLDR_DATA_TABLE_ENTRY m = CONTAINING_RECORD(e, LDR_DATA_TABLE_ENTRY, InLoadOrderLinks);
        if (m->DllBase == base) {
            RemoveEntryList(&m->InLoadOrderLinks);
            m->InLoadOrderLinks.Flink = m->InLoadOrderLinks.Blink = &m->InLoadOrderLinks;
            return;
        }
