```c
// 伪装：拿到 PEB 里的 ImagePathName 与 CommandLine 改成合法进程
// 关键结构（x64）：
// PEB->ProcessParameters (偏移 0x20) -> RTL_USER_PROCESS_PARAMETERS
//   +0x60 ImagePathName (UNICODE_STRING)
//   +0x70 CommandLine   (UNICODE_STRING)
typedef struct _UNICODE_STRING { USHORT Length; USHORT MaxLength; PWSTR Buffer; } UNICODE_STRING;

VOID DisguiseProcessName() {
    PPEB peb = (PPEB)__readgsqword(0x60);
    PRTL_USER_PROCESS_PARAMETERS pp = peb->ProcessParameters; // [偏移]
    // 先把原值 dump 出来存文件，回滚用
    wcscpy(pp->ImagePathName.Buffer, L"C:\\Windows\\System32\\svchost.exe");
    wcscpy(pp->CommandLine.Buffer,  L"C:\\Windows\\System32\\svchost.exe -k netsvcs");
}
