```cpp
// 1) 拿进程与模块基址
#include <windows.h>
#include <TlHelp32.h>
#include <cstdio>

DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (Process32FirstW(snap, &pe)) {
        do {
            if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(snap); return pe.th32ProcessID; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return 0;
}

uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (!_wcsicmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}
```

## 二、读写封装（用户态版，反作弊在内核时改下面第四节）

```cpp
class Mem {
    HANDLE h = nullptr;
public:
    bool Attach(DWORD pid) {
        h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
        return h != nullptr;
    }
    template<typename T> T Read(uintptr_t addr) {
        T v{}; SIZE_T n = 0;
        ReadProcessMemory(h, (LPCVOID)addr, &v, sizeof(T), &n);
        return v;
    }
    template<typename T> bool Write(uintptr_t addr, T v) {
        SIZE_T n = 0;
        return WriteProcessMemory(h, (LPVOID)addr, &v, sizeof(T), &n) && n == sizeof(T);
    }
    uintptr_t ReadChain(uintptr_t base, std::initializer_list<uintptr_t> offs) {
        uintptr_t p = base;
        for (auto o : offs) p = Read<uintptr_t>(p + o);
        return p;
    }
    ~Mem() { if (h) CloseHandle(h); }
};
```

## 三、透视的四个必需量

透视 = **相机矩阵** + **实体列表** + **实体坐标/骨骼** + **W2S 变换**。

