**W2S（世界坐标 → 屏幕坐标）**，UE4/UE5、Unity 通用写法：

```cpp
bool WorldToScreen(const FVec3& w, const FMatrix& vp, int sw, int sh, FVec2& out) {
    float cx = w.x*vp.m[0][0] + w.y*vp.m[1][0] + w.z*vp.m[2][0] + vp.m[3][0];
    float cy = w.x*vp.m[0][1] + w.y*vp.m[1][1] + w.z*vp.m[2][1] + vp.m[3][1];
    float cz = w.x*vp.m[0][2] + w.y*vp.m[1][2] + w.z*vp.m[2][2] + vp.m[3][2];
    float cw = w.x*vp.m[0][3] + w.y*vp.m[1][3] + w.z*vp.m[2][3] + vp.m[3][3];
    if (cw < 0.001f) return false;              // 在相机背后
    float ndc_x = cx / cw, ndc_y = cy / cw;
    out.x = (sw * 0.5f) * (ndc_x + 1.0f);
    out.y = (sh * 0.5f) * (1.0f - ndc_y);
    return true;
}
