## 三、`Driver.c`

```c
#include "Driver.h"

PEPROCESS g_TargetProcess = NULL;

// ---------- 通用的进程附加 ----------
static NTSTATUS
KmAttach(ULONG pid)
{
    PEPROCESS proc = NULL;
    NTSTATUS  st;

    st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    if (g_TargetProcess) ObDereferenceObject(g_TargetProcess);
    g_TargetProcess = proc;

    return STATUS_SUCCESS;
}

// ---------- 读写核心 (MmCopyVirtualMemory) ----------
static NTSTATUS
KmCopyMemory(
    _In_  BOOLEAN  Write,
    _In_  ULONG64  Address,
    _Inout_updates_bytes_(Size) PVOID Buffer,
    _In_  SIZE_T   Size
)
{
    if (!g_TargetProcess) return STATUS_INVALID_PARAMETER;
    if (!Address || !Size) return STATUS_INVALID_PARAMETER;
    if (Size > 0x100000) return STATUS_INVALID_PARAMETER;   // 上限 1MB，防滥用

    KAPC_STATE apc;
    NTSTATUS   st;
    SIZE_T     copied = 0;

    // 让线程在目标进程上下文里跑（关键：否则 MmCopyVirtualMemory 访问跨进程地址失败）
    KeStackAttachProcess(g_TargetProcess, &apc);

    if (Write) {
        st = MmCopyVirtualMemory(
                PsGetCurrentProcess(), Buffer,          // 源: 目标进程? 见下
                g_TargetProcess, (PVOID)Address,        // 目的: 目标进程
                Size, UserMode, &copied);
    } else {
        st = MmCopyVirtualMemory(
                g_TargetProcess, (PVOID)Address,        // 源
                PsGetCurrentProcess(), Buffer,          // 目的
                Size, UserMode, &copied);
    }

    KeUnstackDetachProcess(&apc);
    return st;
}
