// 4x4 矩阵，行主序（UE4/UE5 常见；若列主序需转置）
struct Matrix4x4 { float m[4][4]; };

inline bool WorldToScreen(const XMFLOAT3& world, XMFLOAT2& screen,
                          const Matrix4x4& vm, int screenW, int screenH) {
    // 行向量 * 矩阵：clip = world * vm
    float clipX = world.x * vm.m[0][0] + world.y * vm.m[1][0] + world.z * vm.m[2][0] + vm.m[3][0];
    float clipY = world.x * vm.m[0][1] + world.y * vm.m[1][1] + world.z * vm.m[2][1] + vm.m[3][1];
    float clipW = world.x * vm.m[0][3] + world.y * vm.m[1][3] + world.z * vm.m[2][3] + vm.m[3][3];
    if (clipW < 0.001f) return false;            // 在摄像机后方
    float ndcX = clipX / clipW;
    float ndcY = clipY / clipW;
    screen.x = (ndcX * 0.5f + 0.5f) * (float)screenW;
    screen.y = (1.0f - (ndcY * 0.5f + 0.5f)) * (float)screenH;
    return true;
}

