// 相对移动，dx/dy 单位：kmbox 原始计数（≈ 1 计数 = 1 鼠标 mug 单位）
void KmMouseMove(int dx, int dy) {
    uint8_t f[11] = {0};
    f[0] = 0x02;                       // 相对移动
    f[2] = (uint8_t)(dx & 0xFF);
    f[3] = (uint8_t)((dx >> 8) & 0xFF);
    f[4] = (uint8_t)(dy & 0xFF);
    f[5] = (uint8_t)((dy >> 8) & 0xFF);
    KmWrite(f, 11);
}

void KmMouseLeft(bool down) {
    uint8_t f[11] = {0};
    f[0] = 0x04;
    f[9] = down ? 1 : 0;
    KmWrite(f, 11);
}

void KmMouseWheel(int16_t delta) {
    uint8_t f[11] = {0};
    f[0] = 0x09;
    f[9] = (uint8_t)(delta & 0xFF);
    f[10] = (uint8_t)((delta >> 8) & 0xFF);
    KmWrite(f, 11);
}
