typedef HRESULT(WINAPI* Present_t)(IDXGISwapChain*, UINT, UINT);
Present_t oPresent = nullptr;
ID3D11Device*        g_dev  = nullptr;
ID3D11DeviceContext* g_ctx  = nullptr;
ID3D11RenderTargetView* g_rtv = nullptr;

HRESULT WINAPI hkPresent(IDXGISwapChain* sc, UINT sync, UINT flags) {
    if (!g_dev) {
        sc->GetDevice(__uuidof(ID3D11Device), (void**)&g_dev);
        g_dev->GetImmediateContext(&g_ctx);
        ID3D11Texture2D* back = nullptr;
        sc->GetBuffer(0, __uuidof(ID3D11Texture2D), (void**)&back);
        g_dev->CreateRenderTargetView(back, nullptr, &g_rtv);
        back->Release();
        // 此处初始化 ImGui: ImGui_ImplDX11_Init / ImGui_ImplWin32_Init
    }
    // ImGui::NewFrame(); 绘制 ESP; ImGui::Render();
    return oPresent(sc, sync, flags);
}

// 安装：vtable 第 8 项就是 Present
void InstallHook(IDXGISwapChain* sc) {
    void** vt = *(void***)sc;
    oPresent = (Present_t)vt[8];
    DWORD old;
    VirtualProtect(&vt[8], sizeof(void*), PAGE_EXECUTE_READWRITE, &old);
    vt[8] = hkPresent;
    VirtualProtect(&vt[8], sizeof(void*), old, &old);
}
