```cpp
// build: cl /EHsc /std:c++17 read.cpp /link psapi.lib
#include <windows.h>
#include <psapi.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>
#include <string>

// ---- 1. 找进程 PID ----
DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
        if (!_wcsicmp(pe.szExeFile, name)) { DWORD pid = pe.th32ProcessID; CloseHandle(snap); return pid; }
    CloseHandle(snap);
    return 0;
}

// ---- 2. 取模块基址（用 Toolhelp 拿真实的加载基址，比 EnumProcessModules 更稳） ----
uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me))
        if (!_wcsicmp(me.szModule, mod)) { uintptr_t b = (uintptr_t)me.modBaseAddr; CloseHandle(snap); return b; }
    CloseHandle(snap);
    return 0;
}

// ---- 3. 读写封装 ----
HANDLE g_h = nullptr;
bool   RPM(uintptr_t addr, void* buf, size_t n) { return ReadProcessMemory(g_h, (LPCVOID)addr, buf, n, nullptr) != 0; }
bool   WPM(uintptr_t addr, const void* buf, size_t n) { return WriteProcessMemory(g_h, (LPVOID)addr, buf, n, nullptr) != 0; }
template<class T> T    R(uintptr_t a) { T v{}; RPM(a, &v, sizeof(T)); return v; }
template<class T> bool W(uintptr_t a, T v) { return WPM(a, &v, sizeof(T)); }

// ---- 4. 多级指针链：offs = {0x10, 0x18, 0x2A0, 0x60}，最后一个偏移直接加到实体上 ----
uintptr_t ResolveChain(uintptr_t base, std::vector<uint32_t> offs) {
    uintptr_t p = base;
    for (size_t i = 0; i + 1 < offs.size(); ++i) {
        p = R<uintptr_t>(p + offs[i]);
        if (!p || p < 0x10000) return 0;         // 空指针/非法页提前退出
    }
    return p + offs.back();
}

int main() {
    const wchar_t* proc = L"[进程名].exe";
    const wchar_t* mod  = L"[模块名].dll";
    DWORD pid = FindPid(proc);
    if (!pid) { printf("pid not found\n"); return 1; }
    g_h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!g_h) { printf("OpenProcess failed %lu\n", GetLastError()); return 1; }

    uintptr_t base = GetModuleBase(pid, mod);
    printf("pid=%lu base=%p\n", pid, (void*)base);

    // 占位偏移：静态基址偏移 + 两级指针 + 字段偏移
    const uint32_t baseOff = 0x[基址偏移];
    std::vector<uint32_t> chain = { baseOff, 0x[偏移1], 0x[偏移2], 0x[字段偏移] };
    uintptr_t ent = ResolveChain(base, chain);
    printf("entity=%p\n", (void*)ent);
    if (!ent) return 1;

    // 改一个值验证：dump 原值 → 写 → 读回确认
    int32_t oldVal = R<int32_t>(ent);
    printf("old=%d\n", oldVal);
    W<int32_t>(ent, 0x[目标值]);
    printf("new=%d\n", R<int32_t>(ent));
    return 0;
}
```

