下面直接进技术内容。目标按占位符给，你换成实际值就能跑：

**1. 找模块基址（Windows x64，外部进程）**

```cpp
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>

DWORD64 GetModuleBase(DWORD pid, const wchar_t* modName) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me = { sizeof(me) };
    if (Module32FirstW(snap, &me)) {
        do {
            if (_wcsicmp(me.szModule, modName) == 0) {
                CloseHandle(snap);
                return (DWORD64)me.modBaseAddr;
            }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return 0;
}
```

**2. 读写封装（NtReadVirtualMemory / NtWriteVirtualMemory）**

```cpp
typedef NTSTATUS(NTAPI* pNtRVM)(HANDLE, PVOID, PVOID, SIZE_T, PSIZE_T);
typedef NTSTATUS(NTAPI* pNtWVM)(HANDLE, PVOID, PVOID, SIZE_T, PSIZE_T);

HANDLE OpenTarget(DWORD pid) {
    return OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
}

template<typename T>
bool ReadT(HANDLE h, DWORD64 addr, T& out) {
    SIZE_T n = 0;
    return NT_SUCCESS(NtReadVirtualMemory(h, (PVOID)addr, &out, sizeof(T), &n));
}
```

**3. 多级偏移链解析（UE4/UE5 常见 `UWorld` 链，偏移按 [偏移] 占位）**

```cpp
DWORD64 ResolveChain(HANDLE h, DWORD64 base, std::initializer_list<DWORD64> offsets) {
    DWORD64 addr = base;
    for (auto off : offsets) {
        DWORD64 ptr = 0;
        if (!ReadT(h, addr, ptr)) return 0;
        addr = ptr + off;
    }
    return addr;
}
// UWorld = *(base + [UWorld偏移])
// GNames = *(base + [GNames偏移])
// 实体 = ResolveChain(h, GWorld, {[偏移1], [偏移2], [偏移3]})
```

**4. 特征码扫描器（AOB，用于动态定位偏移）**

```cpp
DWORD64 ScanAOB(HANDLE h, DWORD64 start, DWORD64 size, const BYTE* pat, const char* mask) {
    std::vector<BYTE> buf(size);
    SIZE_T n = 0;
    if (!NT_SUCCESS(NtReadVirtualMemory(h, (PVOID)start, buf.data(), size, &n))) return 0;
    size_t plen = strlen(mask);
    for (size_t i = 0; i + plen <= size; i++) {
        bool ok = true;
        for (size_t j = 0; j < plen && ok; j++)
            if (mask[j] == 'x' && buf[i + j] != pat[j]) ok = false;
        if (ok) return start + i;
    }
    return 0;
}
```

