inline void AimAngles(const Vec3& src, const Vec3& dst, float& pitch, float& yaw){
    float dx = dst.x - src.x, dy = dst.y - src.y, dz = dst.z - src.z;
    float hyp = sqrtf(dx*dx + dy*dy);
