```cpp
#include <windows.h>
#include <tlhelp32.h>
#include <iostream>

// 占位符：[进程名] [模块名]
const wchar_t* PROC = L"[进程名].exe";
const wchar_t* MOD  = L"[模块名].exe";

DWORD GetPid(const wchar_t* name) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    for (BOOL ok = Process32FirstW(h, &pe); ok; ok = Process32NextW(h, &pe))
        if (!_wcsicmp(pe.szExeFile, name)) { DWORD p = pe.th32ProcessID; CloseHandle(h); return p; }
    CloseHandle(h); return 0;
}

uintptr_t GetModBase(DWORD pid, const wchar_t* mod) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    for (BOOL ok = Module32FirstW(h, &me); ok; ok = Module32NextW(h, &me))
        if (!_wcsicmp(me.szModule, mod)) { uintptr_t b = (uintptr_t)me.modBaseAddr; CloseHandle(h); return b; }
    CloseHandle(h); return 0;
}

HANDLE g_h;
template<class T> T RPM(uintptr_t a) { T v{}; ReadProcessMemory(g_h, (LPCVOID)a, &v, sizeof(T), nullptr); return v; }
```

**第二步：实体遍历 —— 从 UWorld 拿玩家链表（UE4/UE5，占位符是偏移）**

```cpp
uintptr_t base = GetModBase(pid, MOD);
// [偏移_UWorld] 等来自动态扫描，未验证前先填占位符
uintptr_t uworld = RPM<uintptr_t>(base + [偏移_UWorld]);      // GWorld 指针
uintptr_t gameInstance = RPM<uintptr_t>(uworld + [偏移_GameInstance]);
uintptr_t localPlayers = RPM<uintptr_t>(gameInstance + [偏移_LocalPlayers]);
uintptr_t localPawn = RPM<uintptr_t>(RPM<uintptr_t>(localPlayers) + [偏移_Pawn]);
uintptr_t persistentLevel = RPM<uintptr_t>(uworld + [偏移_PersistentLevel]);
uintptr_t actors = RPM<uintptr_t>(persistentLevel + [偏移_ActorsArray]);
int actorCount = RPM<int>(persistentLevel + [偏移_ActorsCount]);

for (int i = 0; i < actorCount; i++) {
    uintptr_t actor = RPM<uintptr_t>(actors + i * 8);
    if (!actor || actor == localPawn) continue;
