struct FVector { float x, y, z; };

FVector CalcAngle(const FVector& src, const FVector& dst) {
    FVector d{ dst.x - src.x, dst.y - src.y, dst.z - src.z };
    float hyp = sqrtf(d.x * d.x + d.y * d.y);
    return { atan2f(d.z, hyp) * 57.29578f,          // Pitch
             atan2f(d.y, d.x) * 57.29578f,          // Yaw
             0.f };
}

FVector Smooth(const FVector& cur, const FVector& target, float smoothFactor) {
    FVector delta{ target.x - cur.x, target.y - cur.y, 0.f };
    while (delta.x > 180.f)  delta.x -= 360.f;
    while (delta.x < -180.f) delta.x += 360.f;
    while (delta.y > 180.f)  delta.y -= 360.f;
    while (delta.y < -180.f) delta.y += 360.f;
    return { cur.x + delta.x / smoothFactor,
             cur.y + delta.y / smoothFactor, 0.f };
}

